CREATE TABLE users (id uuid PRIMARY KEY, tenant_key text NOT NULL, open_id text NOT NULL, name text NOT NULL, role text NOT NULL DEFAULT 'Viewer' CHECK (role IN ('Administrator','Production Planner','Warehouse Operator','Manager','Viewer')), disabled boolean NOT NULL DEFAULT false, UNIQUE(tenant_key,open_id));
CREATE TABLE products (id uuid PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL DEFAULT '');
CREATE TABLE suppliers (id uuid PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE variants (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), color_key text NOT NULL, size text NOT NULL CHECK(size IN ('XS','S','M','L','XL','2XL')), body jsonb NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(product_id,color_key,size));
CREATE TABLE inventory_snapshots(id uuid PRIMARY KEY, variant_id uuid NOT NULL REFERENCES variants(id), stock bigint CHECK(stock>=0), inbound bigint NOT NULL CHECK(inbound>=0), source text NOT NULL, at timestamptz NOT NULL, actor_id uuid NOT NULL REFERENCES users(id));
CREATE TABLE planning_policies (id integer PRIMARY KEY CHECK(id=1), body jsonb NOT NULL, version integer NOT NULL DEFAULT 1);
INSERT INTO planning_policies VALUES(1,'{"targetDays":5,"leadDays":3,"safeDays":0,"includeLead":false,"roundTo":1}',1);
CREATE TABLE production_orders (id uuid PRIMARY KEY, code text NOT NULL, supplier_id uuid REFERENCES suppliers(id), body jsonb NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX order_code_unique ON production_orders(lower(code));
CREATE TABLE order_code_reservations(code text PRIMARY KEY, order_id uuid NOT NULL REFERENCES production_orders(id));
CREATE TABLE production_order_items(id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES production_orders(id), variant_id uuid NOT NULL REFERENCES variants(id), qty integer NOT NULL CHECK(qty BETWEEN 1 AND 1000000), received integer NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=qty), priority text NOT NULL CHECK(priority IN ('THƯỜNG','ƯU TIÊN','CẤP BÁCH')), UNIQUE(order_id,variant_id), UNIQUE(id,order_id));
CREATE TABLE production_receipts(id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES production_orders(id), actor_id uuid NOT NULL REFERENCES users(id), date date NOT NULL, note text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,idempotency_key), UNIQUE(id,order_id));
CREATE TABLE production_receipt_items(id uuid PRIMARY KEY, receipt_id uuid NOT NULL, order_id uuid NOT NULL, item_id uuid NOT NULL, qty integer NOT NULL CHECK(qty>0), identity_snapshot jsonb NOT NULL, FOREIGN KEY(receipt_id,order_id) REFERENCES production_receipts(id,order_id), FOREIGN KEY(item_id,order_id) REFERENCES production_order_items(id,order_id), UNIQUE(receipt_id,item_id));
CREATE TABLE production_order_revisions(id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES production_orders(id), actor_id uuid NOT NULL REFERENCES users(id), at timestamptz NOT NULL DEFAULT now(), reason text NOT NULL CHECK(length(trim(reason))>=3), before jsonb NOT NULL, after jsonb NOT NULL);
CREATE TABLE archived_orders(id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES production_orders(id), actor_id uuid NOT NULL REFERENCES users(id), at timestamptz NOT NULL DEFAULT now(), action text NOT NULL CHECK(action IN ('delete','restore')), reason text NOT NULL, snapshot jsonb NOT NULL);
CREATE TABLE activity_logs(id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users(id), at timestamptz NOT NULL DEFAULT now(), action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL);
CREATE TABLE import_previews(id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, body jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sales_imports(id uuid PRIMARY KEY, preview_id uuid NOT NULL UNIQUE REFERENCES import_previews(id), actor_id uuid NOT NULL REFERENCES users(id), filename text NOT NULL, file_hash text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, exported_at timestamptz NOT NULL, mode text NOT NULL CHECK(mode IN ('replace','append')), imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE daily_sales (id uuid PRIMARY KEY, import_id uuid NOT NULL REFERENCES sales_imports(id), line_key text NOT NULL UNIQUE, date date NOT NULL, sku text NOT NULL, color text NOT NULL, size text NOT NULL, qty integer NOT NULL CHECK(qty>=0), kind text NOT NULL CHECK(kind IN ('single','combo','unknown','excluded')), variation text NOT NULL, reason text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE session (sid varchar PRIMARY KEY, sess json NOT NULL, expire timestamp NOT NULL);
CREATE INDEX session_expire_idx ON session(expire);
CREATE INDEX order_items_order_idx ON production_order_items(order_id);
CREATE INDEX sales_date_idx ON daily_sales(date) WHERE active;
CREATE OR REPLACE FUNCTION prevent_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END; $$;
CREATE TRIGGER immutable_receipts BEFORE UPDATE OR DELETE ON production_receipts FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_receipt_items BEFORE UPDATE OR DELETE ON production_receipt_items FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_revisions BEFORE UPDATE OR DELETE ON production_order_revisions FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_activity BEFORE UPDATE OR DELETE ON activity_logs FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_archives BEFORE UPDATE OR DELETE ON archived_orders FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
